"""El Guardián: entrega autónoma. Ver experimentos/arquitectura_fase3.md."""

import math
import re
import unicodedata


def bounded(value, default=0.0):
    try:
        value = float(value)
        return max(0.0, min(1.0, value)) if math.isfinite(value) else default
    except (ValueError, TypeError, OverflowError):
        return default


def normalize(text):
    text = unicodedata.normalize('NFKD', str(text or '').lower())
    return ''.join(c for c in text if not unicodedata.combining(c))


def records(value):
    return [x for x in value if isinstance(x, dict)] if isinstance(value, (list, tuple)) else []


def values(item, name):
    a = item.get(name)
    return [bounded(x) for x in a] if isinstance(a, (list, tuple)) else []


_STOP = set('a al algo ante bajo con contra de del desde el ella ello en entre era es esa ese esta este esto fue ha hacia hasta hay la las lo los mas muy o para pero por que se sin sobre son su sus tanto tras un una unas unos y ya'.split())


def tokens(text):
    return [w for w in re.findall(r'[a-z]+', normalize(text)) if len(w) > 2 and w not in _STOP]


def numbers(text):
    """Normaliza separadores españoles. No convierte aritmética en certeza."""
    out = []
    for raw in re.findall(r'(?<!\w)\d+(?:[.,]\d+)*(?!\w)', normalize(text)):
        try:
            if re.fullmatch(r'\d{1,3}(?:\.\d{3})+(?:,\d+)?', raw):
                raw = raw.replace('.', '').replace(',', '.')
            else:
                raw = raw.replace(',', '.')
            out.append(float(raw))
        except ValueError:
            pass
    return out


_MARKERS = {
    'causa': (r'\bgracias a\b', r'\bdebido a\b', r'\ba causa de\b', r'\bpor lo (?:que|tanto)\b', r'\bpermiti\w*\b', r'\bprovoc\w*\b', r'\bporque\b', r'\bpara (?:garantizar|mejorar|reducir|evitar)\b'),
    'alcance': (r'\btod[oa]s?\b', r'\bsiempre\b', r'\bnunca\b', r'\bcualquier\b', r'\b(?:el|la) unic[oa]\b', r'\b(?:del|en el) pais\b', r'\bsin excepcion\b', r'\bgarantiz\w*\b'),
    'certeza': (r'\baprobo\b', r'\baprobado\b', r'\binmuniz\w*\b', r'\bdefinitiv\w*\b', r'\bdemuestr\w*\b', r'\bobligatori\w*\b'),
}


def extract_features(caso, include_numeric=True):
    caso = caso if isinstance(caso, dict) else {}
    signals = caso.get('senales')
    signals = signals if isinstance(signals, dict) else {}
    sentences = records(signals.get('oraciones'))
    fragments = records(signals.get('fragmentos'))
    raw_sources = caso.get('fuentes')
    sources = [str(s or '') for s in raw_sources] if isinstance(raw_sources, (list, tuple)) else []
    source_tokens = [set(tokens(s)) for s in sources]
    union_tokens = set().union(*source_tokens) if sources else set()
    all_sources = normalize(' '.join(sources))
    answer = str(caso.get('respuesta') or '')
    features = {}

    def aggregate(prefix, rows):
        keys = sorted(set().union(*(r.keys() for r in rows))) if rows else []
        for key in keys:
            a = sorted(r.get(key, 0.0) for r in rows)
            features[prefix+key+'_min'] = a[0]
            features[prefix+key+'_max'] = a[-1]
            features[prefix+key+'_mean'] = sum(a)/len(a)
        # Empty sets must have exactly the same columns as ordinary examples.
        return keys

    def item_row(item):
        support = values(item, 'respaldo_por_fuente')
        contradiction = values(item, 'contradiccion_por_fuente')
        similarity = values(item, 'similitud_por_fuente')
        best = max(support, default=0.0)
        joint = bounded(item.get('respaldo_todas'))
        combined = max(best, joint)
        most_similar = max(range(len(similarity)), key=similarity.__getitem__) if similarity else -1
        most_support = max(range(len(support)), key=support.__getitem__) if support else -1
        at_similar = support[most_similar] if 0 <= most_similar < len(support) else 0.0
        c_at_support = contradiction[most_support] if 0 <= most_support < len(contradiction) else 0.0
        c_at_similar = contradiction[most_similar] if 0 <= most_similar < len(contradiction) else 0.0
        return {'individual':best, 'conjunto':joint,
                'mejor':combined, 'ganancia_conjunto':joint-best,
                'contradiccion_conjunto':bounded(item.get('contradiccion_todas')),
                'contradiccion_fuente':max(contradiction, default=0.0),
                'contradiccion_alineada':c_at_similar,
                'contradiccion_respaldante':c_at_support,
                'respaldo_alineado':at_similar,
                'similitud':max(similarity, default=0.0),
                'riesgo':1-combined,
                'neutralidad':max(0.0,1-joint-bounded(item.get('contradiccion_todas')))}

    # A placeholder gives stable columns on missing signals, with missing flags.
    sentence_rows = [item_row(s) for s in sentences] or [item_row({})]
    fragment_rows = [item_row(s) for s in fragments] or [item_row({})]
    aggregate('s_', sentence_rows)
    aggregate('f_', fragment_rows)
    llm_rows = []
    for sentence, row in zip(sentences, sentence_rows):
        llm = sentence.get('llm')
        llm = llm if isinstance(llm, dict) else {}
        verdict = llm.get('veredicto')
        confidence = bounded(llm.get('confianza'), .5)
        risk = (1-confidence)/2 if verdict=='respaldada' else (.5+confidence/2 if verdict in ('no_respaldada','contradicha') else .5)
        llm_rows.append({'riesgo':risk, 'no_respaldada':float(verdict=='no_respaldada'),
                         'contradicha':float(verdict=='contradicha'), 'ausente':float(verdict not in ('respaldada','no_respaldada','contradicha')),
                         'confianza_respaldada':confidence if verdict=='respaldada' else 0.0})
        row['desacuerdo'] = row['riesgo']-risk
        row['optimismo_llm'] = row['riesgo']*(1-risk)
        row['pesimismo_llm'] = risk*(1-row['riesgo'])
    aggregate('l_', llm_rows or [{'riesgo':.5,'no_respaldada':0.,'contradicha':0.,'ausente':1.,'confianza_respaldada':0.}])
    for key in ['desacuerdo','optimismo_llm','pesimismo_llm']:
        a=[r.get(key,0.0) for r in sentence_rows]
        features['d_'+key+'_max']=max(a)
        features['d_'+key+'_mean']=sum(a)/len(a)
    features['d_fragmento_oracion'] = max(r['riesgo'] for r in fragment_rows)-max(r['riesgo'] for r in sentence_rows)
    features['missing_oraciones'] = float(not sentences)
    features['missing_fragmentos'] = float(not fragments)

    lexical_rows=[]
    for item in sentences+fragments or [{'texto':answer}]:
        ts=set(tokens(item.get('texto','')))
        most = max((len(ts & s)/max(1,len(ts)) for s in source_tokens),default=0.0)
        lexical_rows.append({'novedad':len(ts-union_tokens)/max(1,len(ts)), 'cobertura_individual':most})
    aggregate('texto_',lexical_rows)
    ansnorm = normalize(answer)
    for name,patterns in _MARKERS.items():
        features['texto_'+name+'_nuevo'] = float(any(re.search(p,ansnorm) and not re.search(p,all_sources) for p in patterns))
    if not include_numeric:
        return features
    # Numeric mismatch and local source context are signals, never hard gates.
    source_nums=set(numbers(' '.join(sources)))
    ansnums=numbers(answer)
    unmatched=[n for n in ansnums if n not in source_nums]
    features['num_ausente']=len(unmatched)/max(1,len(ansnums))
    features['num_hay']=float(bool(ansnums))
    # Legal arithmetic/conversions reduce suspicion but do not validate attribution.
    convertible=set(source_nums)
    if len(source_nums) <= 80:
        for n in source_nums:
            convertible.update([n*1000,n/1000,n*100,n/100,n*2,n/2])
            for m in source_nums:
                convertible.update([n+m,abs(n-m)])
    features['num_sin_conversion']=sum(not any(math.isclose(n,m,rel_tol=1e-7,abs_tol=1e-7) for m in convertible) for n in ansnums)/max(1,len(ansnums))
    local=[]
    for item in sentences or [{'texto':answer}]:
        text=str(item.get('texto') or '')
        ts=set(tokens(text))
        if not source_tokens or not numbers(text):
            continue
        # Compare the number to all sources within 90% of best lexical coverage.
        overlaps=[len(ts&s)/max(1,len(ts)) for s in source_tokens]
        best=max(overlaps)
        near=' '.join(s for s,o in zip(sources,overlaps) if o>=.9*best)
        ns=set(numbers(near))
        local.append(sum(n not in ns for n in numbers(text))/len(numbers(text)))
    features['num_contexto']=max(local,default=0.0)
    return features


def features_for(caso, ablation=None):
    """Misma extracción en entrenamiento y entrega para las ablaciones."""
    if ablation in ('sin_conjunto', 'sin_contradiccion_fuente'):
        import copy
        caso = copy.deepcopy(caso) if isinstance(caso, dict) else {}
        signals = caso.get('senales')
        if isinstance(signals, dict):
            for section in ('oraciones', 'fragmentos'):
                for item in records(signals.get(section)):
                    if ablation == 'sin_conjunto':
                        item['respaldo_todas'] = 0.0
                    else:
                        item['contradiccion_por_fuente'] = []
    f = extract_features(caso, include_numeric=ablation != 'sin_numeros')
    if ablation == 'sin_fragmentos':
        f = {k:v for k,v in f.items() if not k.startswith(('f_', 'missing_fragmentos', 'd_fragmento'))}
    if ablation == 'sin_minimax':
        f = {k:v for k,v in f.items() if not k.startswith(('l_', 'd_desacuerdo', 'd_optimismo', 'd_pesimismo'))}
    return f

