def _sigmoid(x):
    x = max(-700.0, min(700.0, x))
    return 1.0 / (1.0 + math.exp(-x))



"""Comprobaciones estrechas de relaciones explícitas. Abstención fuera de cobertura.

No usa IDs/etiquetas ni nombres específicos. No interpreta números en palabras.
"""
_SCI_NUM=r'(?<!\w)\d+(?:[.,]\d+)*(?!\w)'
_SCI_ENT_STOP=set('el la los las un una unos unas en de del al con sin para por durante desde su sus se no si este esta estos estas es son fue hay apartado articulo capitulo anexo'.split())


def sci_quantities(text):
    normalized=normalize(text);out=[]
    for match in re.finditer(_SCI_NUM,normalized):
        if (match.start()>0 and normalized[match.start()-1] in ':/') or (match.end()<len(normalized) and normalized[match.end()] in ':/'):continue
        raw=match.group();after=normalized[match.end():match.end()+42]
        try:
            thousands=bool(re.fullmatch(r'\d{1,3}(?:\.\d{3})+(?:,\d+)?',raw))
            number=float(raw.replace('.','').replace(',','.')) if thousands else float(raw.replace(',','.'))
        except ValueError:continue
        if not math.isfinite(number) or number>1e15:continue
        decimals=len(raw.split(',')[-1]) if ',' in raw else (len(raw.split('.')[-1]) if '.' in raw and not thousands else 0)
        scale=1.;unit='number'
        if re.match(r'\s*(?:%|por ciento)',after):unit='percent'
        elif re.match(r'\s*(?:millones?|miles?)\b',after):unit='amount';scale=1e6 if re.match(r'\s*mill',after) else 1e3
        elif re.match(r'\s*(?:centimos?|centavos?)\b',after):unit='amount';scale=.01
        elif re.match(r'\s*(?:euros?|€)\b',after):unit='amount'
        elif re.match(r'\s*mes(?:es)?\b',after):unit='months'
        elif re.match(r'\s*(?:kilometros?|km)\b',after):unit='length';scale=1000.
        elif re.match(r'\s*(?:metros?|m)\b',after):unit='length'
        elif re.match(r'\s*(?:hectareas?|ha)\b',after):unit='area'
        elif re.match(r'\s*(?:toneladas?|t)\b',after):unit='mass';scale=1000.
        elif re.match(r'\s*(?:kilogramos?|kg)\b',after):unit='mass'
        elif re.match(r'\s*(?:trabajadores?|personas?|habitantes?|alumnos?|participantes?|empleados?)\b',after) or re.match(r'\s*el numero de (?:trabajadores|personas)',after):unit='people'
        elif re.match(r'\s*(?:horas?)\b',after):unit='time';scale=60.
        elif re.match(r'\s*(?:minutos?)\b',after):unit='time'
        elif 1900<=number<=2100 and number.is_integer():unit='year'
        if unit=='amount' and re.match(r'\s*(?:euros?|€)\s+(?:al|por)\s+mes\b',after):unit='amount_per_month'
        out.append(dict(value=number*scale,tolerance=.500001*10**(-decimals)*scale,unit=unit,scale=scale,start=match.start(),end=match.end(),raw=raw))
    # Ellipsis of a shared unit: only infer if there is exactly one explicit unit/scale.
    explicit={(q['unit'],q['scale']) for q in out if q['unit'] not in ('number','year','percent')}
    if len(explicit)==1:
        unit,scale=next(iter(explicit))
        for q in out:
            if q['unit']=='number':q['value']*=scale;q['tolerance']*=scale;q['unit']=unit;q['scale']=scale
    return out


def sci_entity_tokens(text):
    raw=re.findall(r'\b[A-ZÁÉÍÓÚÜÑ][A-Za-zÁÉÍÓÚÜÑáéíóúüñ-]+\b',str(text or ''))
    entities={normalize(w) for w in raw if normalize(w) not in _SCI_ENT_STOP and len(w)>2}
    # Generic explicit labels, e.g. empresa A / plan B, without memorizing values.
    labels=re.findall(r'\b(?:empresa|producto|plan|tarifa|modelo)\s+([A-Z][\w-]*)',str(text or ''),flags=re.I)
    entities.update(normalize(w) for w in labels)
    return entities


def sci_relations(caso):
    caso=caso if isinstance(caso,dict) else {};sources=caso.get('fuentes');sources=sources if isinstance(sources,(list,tuple)) else []
    sources=[str(s or '') for s in sources];answer=str(caso.get('respuesta') or '')
    result={key:0 for key in ['pair_checked','pair_bad','source_math_checked','source_math_bad','binding_checked','binding_bad']}
    source_clauses=[part for s in sources for part in re.split(r'(?<=[.!?])\s+(?=[A-ZÁÉÍÓÚÜÑ])',s) if part.strip()]
    universe=set().union(*(sci_entity_tokens(s) for s in sources)) if sources else set()
    clauses=re.split(r'(?<=[.!?])\s+(?=[A-ZÁÉÍÓÚÜÑ])',answer)
    for clause in clauses:
        text=normalize(clause)
        # Unknown written quantities can be a result or an operand: abstain.
        if re.search(r'\b(dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce|trece|catorce|quince|dieciseis|diecisiete|dieciocho|diecinueve|veinte|treinta|cuarenta|cincuenta|sesenta|setenta|ochenta|noventa|cien|ciento|doscientos|trescientos|mil)\b',text):continue
        quantities=sci_quantities(clause);qs=[q for q in quantities if q['unit']!='year']
        # Explicit pair de A a B, plus a stated difference or percentage.
        pair=re.search(r'\b(?:de|desde)\s+('+_SCI_NUM+r')\s*(?:[a-z€%]+\s+){0,3}a\s+('+_SCI_NUM+r')',text)
        handled=False
        if pair:
            first=next((q for q in qs if q['start']==pair.start(1)),None);second=next((q for q in qs if q['start']==pair.start(2)),None)
            rest=[q for q in qs if q is not first and q is not second]
            if first and second and len(rest)==1 and first['unit']==second['unit']:
                stated=rest[0];expected=None
                if stated['unit']=='percent' and first['value'] and re.search(r'\b(aument\w*|crec\w*|redu\w*|cay\w*|baj\w*)\b',text):expected=100*abs(second['value']-first['value'])/abs(first['value'])
                elif stated['unit']==first['unit'] and re.search(r'\b(mas|menos|diferencia|incremento|aumento|reduccion)\b',text):expected=abs(second['value']-first['value'])
                if expected is not None:
                    result['pair_checked']+=1;result['pair_bad']+=int(abs(stated['value']-expected)>stated['tolerance']+1e-8*max(1.,abs(expected)));handled=True
        if handled:continue
        claim_entities=sci_entity_tokens(clause)&universe
        claim_words=set(tokens(clause));candidates=[]
        for source in source_clauses:
            source_words=set(tokens(source));common=len(claim_words&source_words)
            coverage=common/max(1,len(claim_words))
            named=sci_entity_tokens(source)
            if common>=3 and coverage>=.35 and claim_entities<=named:
                candidates.append((coverage,source))
        candidates.sort(key=lambda x:x[0],reverse=True)
        # Source arithmetic: one declared result and 2–4 quantities of the same unit.
        is_sum=bool(re.search(r'\b(sum\w*|en total)\b',text));is_diff=bool(re.search(r'\b(super\w*|diferencia|mas que|menos que|respecto)\b',text))
        if len(qs)==1 and (is_sum or is_diff) and candidates:
            q=qs[0];best=candidates[0][1];source_q=[x for x in sci_quantities(best) if x['unit']!='year']
            nonentity=len((claim_words-claim_entities)&(set(tokens(best))-universe))
            clear_entity_sum=is_sum and len(claim_entities)>=2 and len(source_q)==len(claim_entities)
            if (nonentity>=2 or clear_entity_sum) and 2<=len(source_q)<=4 and all(x['unit']==q['unit'] for x in source_q) and (is_sum or len(source_q)==2):
                expected=sum(x['value'] for x in source_q) if is_sum else abs(source_q[0]['value']-source_q[1]['value'])
                result['source_math_checked']+=1;result['source_math_bad']+=int(abs(q['value']-expected)>q['tolerance']+sum(x['tolerance'] for x in source_q)*.01+1e-8*max(1.,abs(expected)))
                continue
        # Entity/date binding: single explicit entity, one quantity, clear predicate
        # overlap, and a unique relevant source. No flag merely for absent numbers.
        if len(claim_entities)==1 and len(quantities)==1 and candidates:
            coverage,source=candidates[0]
            if coverage<.6 or (len(candidates)>1 and coverage-candidates[1][0]<.15):continue
            sq=sci_quantities(source);q=quantities[0]
            if len(sq)!=1 or sq[0]['unit']!=q['unit']:continue
            # Only a cross-source collision supplies positive evidence of misbinding.
            other=[x for s in source_clauses if not claim_entities<=sci_entity_tokens(s) for x in sci_quantities(s) if x['unit']==q['unit']]
            present_elsewhere=any(abs(x['value']-q['value'])<=max(x['tolerance'],q['tolerance']) for x in other)
            result['binding_checked']+=1
            result['binding_bad']+=int(present_elsewhere and abs(sq[0]['value']-q['value'])>max(sq[0]['tolerance'],q['tolerance']))
    return result


def sci_relation_risk(caso):
    r=sci_relations(caso)
    return .99 if r['pair_bad']+r['source_math_bad']+r['binding_bad'] else 0.


_SCI_THRESHOLD = 0.145795691981
_SCI_RULE_WEIGHT = 1.0


def _sci_native_baseline(features):
    p = _PARAMETERS
    x = [features[k] for k in p['features']]
    total = p['bias']
    for tree in p['trees']:
        i = 0
        while not tree[i][5]:
            node = tree[i]
            i = node[0] if x[node[2]] <= node[3] else node[1]
        total += tree[i][4]
    return _sigmoid(total)


class Guardian:
    """HGB original y comprobaciones de relaciones, sin archivos ni red."""
    def score(self, caso) -> float:
        f = features_for(caso, 'sin_numeros')
        if f['missing_oraciones'] and f['missing_fragmentos']:
            return 0.75
        raw = _sci_native_baseline(f)
        corrected = round(max(raw, sci_relation_risk(caso)), 12)
        raw = corrected if _SCI_RULE_WEIGHT == 1.0 else round(.5*raw + .5*corrected, 12)
        t = max(1e-9, min(1-1e-9, _SCI_THRESHOLD))
        return bounded(.5*raw/t if raw < t else .5+.5*(raw-t)/(1-t))
